def parse_kv(s):
    """
    Parse a key=value; key=value string into a dict.

    Semicolons separate pairs; the first '=' separates key from value;
    keys and values are whitespace-trimmed; a backslash-escaped semicolon \; 
    is a literal semicolon in a value.

    An empty string yields an empty dict.

    Args:
        s (str): The string to parse

    Returns:
        dict: Parsed key-value pairs
    """
    if not s:
        return {}

    result = {}
    # Split by unescaped semicolons
    pairs = []
    current_pair = ""
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s) and s[i + 1] == ';':
            # Escaped semicolon, include it literally
            current_pair += ';'
            i += 2
        elif s[i] == ';':
            # Unescaped semicolon, this is a separator
            pairs.append(current_pair)
            current_pair = ""
            i += 1
        else:
            current_pair += s[i]
            i += 1
    # Add the last pair
    if current_pair or pairs:
        pairs.append(current_pair)

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            result[key.strip()] = value.strip()

    return result

import pytest
from parse_kv import parse_kv


def test_empty_string():
    """An empty string yields an empty dict."""
    assert parse_kv("") == {}


def test_single_pair():
    """Test parsing a single key-value pair."""
    assert parse_kv("key1=value1") == {"key1": "value1"}


def test_multiple_pairs():
    """Test parsing multiple key-value pairs."""
    result = parse_kv("key1=value1; key2=value2")
    assert result == {"key1": "value1", "key2": "value2"}


def test_whitespace_trimming():
    """Test that keys and values are whitespace-trimmed."""
    result = parse_kv("  key1  =  value1  ;  key2  =  value2  ")
    assert result == {"key1": "value1", "key2": "value2"}


def test_escaped_semicolon():
    """Test that escaped semicolons are literal semicolons in values."""
    result = parse_kv("key1=value\\;with\\;semicolons")
    assert result == {"key1": "value;with;semicolons"}


def test_escaped_semicolon_with_other_pairs():
    """Test escaped semicolons mixed with other pairs."""
    result = parse_kv("key1=val\\;ue; key2=value2")
    assert result == {"key1": "val;ue", "key2": "value2"}


def test_value_with_equals():
    """Test value containing equals sign (first = is separator)."""
    result = parse_kv("key1=val=ue")
    assert result == {"key1": "val=ue"}


def test_multiple_pairs_with_escaped_semicolon():
    """Test multiple pairs with escaped semicolons."""
    result = parse_kv("k1=v\\;al; k2=v2\\;al2")
    assert result == {"k1": "v;al", "k2": "v2;al2"}


def test_realistic_example():
    """Test a realistic example with multiple features."""
    result = parse_kv("name=John Doe; age=30; city=New York")
    assert result == {"name": "John Doe", "age": "30", "city": "New York"}


def test_realistic_with_escaped():
    """Test realistic example with escaped semicolons in values."""
    result = parse_kv("query=hello\\;world; limit=10")
    assert result == {"query": "hello;world", "limit": "10"}

